live.schedule:
const currentDatetime = new Date($('Edit Fields').first().json.now);
const appointmentStart = new Date($input.first().json.output.utc_dateTime_ISO);

// Check if appointment is at least 24 or 12 hours from now
const isAtLeast24Hours = appointmentStart.getTime() - currentDatetime.getTime() >= 24 * 60 * 60 * 1000;
const isAtLeast12Hours = appointmentStart.getTime() - currentDatetime.getTime() >= 12 * 60 * 60 * 1000;

// Calculate time offsets
const nineteenHoursBefore = new Date(appointmentStart.getTime() - 19 * 60 * 60 * 1000);
const twelveHoursBefore = new Date(appointmentStart.getTime() - 12 * 60 * 60 * 1000);
const fiveHoursBefore = new Date(appointmentStart.getTime() - 5 * 60 * 60 * 1000);
const tenMinutesBefore = new Date(appointmentStart.getTime() - 10 * 60 * 1000);

return [
  {
    json: {
      isAtLeast24Hours: isAtLeast24Hours ? "y" : "n",
      isAtLeast12Hours: isAtLeast12Hours ? "y" : "n",
      nineteen_hours_before: nineteenHoursBefore.toISOString(),
      twelve_hours_before: twelveHoursBefore.toISOString(),
      five_hours_before: fiveHoursBefore.toISOString(),
      ten_minutes_before: tenMinutesBefore.toISOString()
    }
  }
];

live.quiet:
return items.map(item => {
  const lastMessageMs = item.json.conversations[0].lastMessageDate;

  if (!lastMessageMs) {
    return { json: { result: null, reason: "No lastMessageDate found" } };
  }

  const nowMs = Date.now();
  const diffDays = (nowMs - lastMessageMs) / (1000 * 60 * 60 * 24);
  const isOver3Weeks = diffDays > 21;

  return { json: { result: isOver3Weeks } };
});
